import "math"

// Chunk splits s into chunks of at most n (n>=1)
func Chunk[T any](s []T, n int) [][]T {
	if n < 1 {
		return [][]T{}
	}
	chunks := make([][]T, 0, math.Ceil(float64(len(s))/float64(n)))
	for i := 0; i < len(s); i += n {
		if i+n > len(s) {
			chunks = append(chunks, s[i:])
		} else {
			chunks = append(chunks, s[i:i+n])
		}
	}
	return chunks
}

