func (r *Ring) Push(v int) {
	if r.size == r.cap {
		r.pop()
	}
	r.items = append(r.items, v)
	r.size++
}

func (r *Ring) pop() {
	r.items[0] = 0
	r.items = r.items[1:]
	r.size--
}

