import (
	"sync"
)

func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	var wg sync.WaitGroup
	wg.Add(len(nums))

	for i := 0; i < workers; i++ {
		go func() {
			for j := range jobs {
				wg.Done()
			}
		}()
	}

	for _, num := range nums {
		jobs <- num
	}
	close(jobs)

	wg.Wait()
	return len(nums)
}

