func CountUntil(ctx context.Context, ch <-chan int) int {
	count := 0
	for {
		select {
		case <-ctx.Done():
			return count
		case <-time.After(1 * time.Second):
			continue
		case i := <-ch:
			count = i
		}
	}
}

