	"sync"
)

func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var (
		chunks [][]byte
		err    error
	)

	var wg sync.WaitGroup
	wg.Add(1)

	go func() {
		defer wg.Done()
		buf := make([]byte, size)
		for {
			n, err := r.Read(buf)
			if err != nil {
				break
			}
			chunks = append(chunks, buf[:n])
		}
	}()

	wg.Wait()
	return chunks, err
}

